pub fn emit_simple_expr(
    expr: Rc<Node>,
    target: RenderTarget,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.expr_data.clone()).clone() {
            ExprData::ExprLiteral { value: v, .. } => emit_literal(v.clone(), target.clone()),
            ExprData::ExprError { message, .. } => emit_error_expr(message.clone(), target.clone()),
            ExprData::ExprVar {
                binding_kind: _, ..
            } => emit_ident(
                expr_var_name_at(expr.clone(), source_indices.clone()),
                target.clone(),
            ),
            ExprData::ExprFieldAccess { summary: _, .. } => {
                let f = field_access_field_at(expr.clone(), source_indices.clone());
                let b = field_access_base(expr.clone());
                if is_typed_service_call_receiver(expr.clone(), source_indices.clone()) {
                    match extract_typed_service_name(expr.clone(), source_indices.clone()) {
                        Some(svc_name) => service_var_name(svc_name.clone()),
                        None => v1_rt::concat(
                            v1_rt::concat(
                                emit_simple_expr(b.clone(), target.clone(), source_indices.clone()),
                                ".".to_string(),
                            ),
                            emit_ident(f.clone(), target.clone()),
                        ),
                    }
                } else {
                    {
                        let base_is_fn = match (*b.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: bk, ..
                            } => match bk.clone().as_deref().cloned() {
                                Some(VarBindingKind::MatchBoundBinding) => false,
                                Some(VarBindingKind::VariantValueBinding {
                                    parent_enum: _,
                                    ..
                                }) => false,
                                _ => true,
                            },
                            _ => false,
                        };
                        let base_str =
                            emit_simple_expr(b.clone(), target.clone(), source_indices.clone());
                        let base_call = if base_is_fn.clone() {
                            v1_rt::concat(base_str.clone(), "()".to_string())
                        } else {
                            base_str.clone()
                        };
                        let field_str = v1_rt::concat(
                            v1_rt::concat(base_call.clone(), ".".to_string()),
                            emit_ident(f.clone(), target.clone()),
                        );
                        let needs_clone = (base_is_fn.clone()
                            && match target.clone() {
                                RenderTarget::Rust => true,
                                _ => false,
                            });
                        if needs_clone.clone() {
                            v1_rt::concat(field_str.clone(), ".clone()".to_string())
                        } else {
                            field_str.clone()
                        }
                    }
                }
            }
            ExprData::ExprStringInterp => {
                let ps = Rc::new({
                    let mut __result = Vec::new();
                    for child in expr.children.clone().iter().cloned() {
                        __result.push(match (*child.expr_data.clone()).clone() {
                            ExprData::ExprLiteral { ref value, .. } => {
                                let LiteralValue::LitStr { value: text, .. } = value.as_ref()
                                else {
                                    unreachable!()
                                };
                                Rc::new(StringPart::Text {
                                    value: text.clone(),
                                })
                            }
                            _ => Rc::new(StringPart::Interpolation {
                                expr: arg_value(child.clone()),
                            }),
                        });
                    }
                    __result
                });
                emit_simple_string_interp(ps.clone(), target.clone(), source_indices.clone())
            }
            ExprData::ExprListLit => match target.clone() {
                RenderTarget::Go => emit_error_expr(
                    "list literal in simple expr not yet supported for Go".to_string(),
                    target.clone(),
                ),
                _ => {
                    let el_strs = Rc::new({
                        let mut __result = Vec::new();
                        for e in expr.children.clone().iter().cloned() {
                            __result.push(emit_simple_expr(
                                e.clone(),
                                target.clone(),
                                source_indices.clone(),
                            ));
                        }
                        __result
                    });
                    v1_rt::concat(
                        v1_rt::concat("[".to_string(), el_strs.clone().join(&", ".to_string())),
                        "]".to_string(),
                    )
                }
            },
            ExprData::ExprRecordLit { parent_enum: _, .. } => match target.clone() {
                RenderTarget::Go => emit_error_expr(
                    "record literal in simple expr not yet supported for Go".to_string(),
                    target.clone(),
                ),
                _ => {
                    let field_strs = Rc::new({
                        let mut __result = Vec::new();
                        for f in expr.children.clone().iter().cloned() {
                            __result.push(v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        "\"".to_string(),
                                        field_init_node_name_at(f.clone(), source_indices.clone()),
                                    ),
                                    "\": ".to_string(),
                                ),
                                emit_simple_expr(
                                    field_init_node_value(f.clone()),
                                    target.clone(),
                                    source_indices.clone(),
                                ),
                            ));
                        }
                        __result
                    });
                    v1_rt::concat(
                        v1_rt::concat("{".to_string(), field_strs.clone().join(&", ".to_string())),
                        "}".to_string(),
                    )
                }
            },
            _ => emit_error_expr(
                "unsupported simple expr in test/mock binding".to_string(),
                target.clone(),
            ),
        }
    })
}

pub fn emit_simple_string_interp(
    parts: Rc<Vec<Rc<StringPart>>>,
    target: RenderTarget,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let spec = language_spec(target.clone());
        let interp = spec.string_interp.clone();
        let has_interpolations = {
            let mut __found = false;
            for p in parts.clone().iter().cloned() {
                if match (*p.clone()).clone() {
                    StringPart::Interpolation { expr: _, .. } => true,
                    _ => false,
                } {
                    __found = true;
                    break;
                }
            }
            __found
        };
        match (*interp.style.clone()).clone() {
            InterpStyle::FormatArgs {
                placeholder: ph, ..
            } => {
                let fmt_parts = Rc::new({
                    let mut __result = Vec::new();
                    for p in parts.clone().iter().cloned() {
                        __result.push(match (*p.clone()).clone() {
                            StringPart::Text { value: v, .. } => {
                                let base = escape_string_literal_body(v.clone());
                                let escaped = if has_interpolations.clone() {
                                    apply_escape_pairs(base.clone(), interp.escape_pairs.clone())
                                } else {
                                    base.clone()
                                };
                                Rc::new(InterpPart {
                                    format_segment: escaped.clone(),
                                    arg_expr: "".to_string(),
                                })
                            }
                            StringPart::Interpolation { expr: e, .. } => Rc::new(InterpPart {
                                format_segment: ph.clone(),
                                arg_expr: emit_simple_expr(
                                    e.clone(),
                                    target.clone(),
                                    source_indices.clone(),
                                ),
                            }),
                        });
                    }
                    __result
                });
                let fmt_str = Rc::new({
                    let mut __result = Vec::new();
                    for p in fmt_parts.clone().iter().cloned() {
                        __result.push(p.format_segment.clone());
                    }
                    __result
                })
                .join(&"".to_string());
                let args = Rc::new({
                    let mut __result = Vec::new();
                    for a in Rc::new({
                        let mut __result = Vec::new();
                        for p in fmt_parts.clone().iter().cloned() {
                            __result.push(p.arg_expr.clone());
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    {
                        if (a.clone() != "".to_string()) {
                            __result.push(a);
                        }
                    }
                    __result
                });
                if ((args.clone().len() as i64) == 0) {
                    apply_type_template1(interp.plain_template.clone(), fmt_str.clone())
                } else {
                    {
                        let args_str = args.clone().join(&", ".to_string());
                        apply_type_template2(
                            interp.format_template.clone(),
                            fmt_str.clone(),
                            args_str.clone(),
                        )
                    }
                }
            }
            InterpStyle::InlineExpr => {
                let segments = Rc::new({
                    let mut __result = Vec::new();
                    for p in parts.clone().iter().cloned() {
                        __result.push(match (*p.clone()).clone() {
                            StringPart::Text { value: v, .. } => {
                                let base = escape_string_literal_body(v.clone());
                                if has_interpolations.clone() {
                                    apply_escape_pairs(base.clone(), interp.escape_pairs.clone())
                                } else {
                                    base.clone()
                                }
                            }
                            StringPart::Interpolation { expr: e, .. } => v1_rt::concat(
                                v1_rt::concat(
                                    "{".to_string(),
                                    emit_simple_expr(
                                        e.clone(),
                                        target.clone(),
                                        source_indices.clone(),
                                    ),
                                ),
                                "}".to_string(),
                            ),
                        });
                    }
                    __result
                });
                apply_type_template1(
                    interp.format_template.clone(),
                    segments.clone().join(&"".to_string()),
                )
            }
        }
    }
}

