pub fn order_typed_call_args(
    args: Rc<Vec<Rc<Node>>>,
    func: String,
    scope: Rc<InferScope>,
) -> Rc<Vec<Rc<Node>>> {
    {
        let has_unnamed = {
            let mut __found = false;
            for arg in args.clone().iter().cloned() {
                if (arg_name_at(arg.clone(), scope.type_env.clone().source_indices.clone()) == None)
                {
                    __found = true;
                    break;
                }
            }
            __found
        };
        if has_unnamed.clone() {
            args.clone()
        } else {
            match lookup_func_sig_in_scope(scope.clone(), func.clone()) {
                None => args.clone(),
                Some(sig) => {
                    let arg_map = args.clone().iter().cloned().fold(
                        v1_rt::rc_empty_map::<String, Rc<Node>>(),
                        |acc: Rc<HashMap<String, Rc<Node>>>, arg: Rc<Node>| {
                            let n = arg_name_at(
                                arg.clone(),
                                scope.type_env.clone().source_indices.clone(),
                            );
                            if (n.clone() != None) {
                                v1_rt::rc_map_insert(acc.clone(), n.clone().unwrap(), arg.clone())
                            } else {
                                acc.clone()
                            }
                        },
                    );
                    let param_name_set = sig.params.clone().iter().cloned().fold(
                        v1_rt::rc_empty_map::<String, bool>(),
                        |acc: Rc<HashMap<String, bool>>, param: Rc<Node>| {
                            v1_rt::rc_map_insert(
                                acc,
                                param_node_name_at(
                                    param.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                ),
                                true,
                            )
                        },
                    );
                    let ordered = Rc::new({
                        let mut __result = Vec::new();
                        for param in sig.params.clone().iter().cloned() {
                            __result.extend(
                                (*match v1_rt::map_get(
                                    &arg_map,
                                    param_node_name_at(
                                        param.clone(),
                                        scope.type_env.clone().source_indices.clone(),
                                    ),
                                ) {
                                    Some(arg) => Rc::new(vec![arg.clone()]),
                                    None => Rc::new(vec![]),
                                })
                                .iter()
                                .cloned(),
                            );
                        }
                        __result
                    });
                    let leftovers = Rc::new({
                        let mut __result = Vec::new();
                        for arg in args.clone().iter().cloned() {
                            if {
                                let n = arg_name_at(
                                    arg.clone(),
                                    scope.type_env.clone().source_indices.clone(),
                                );
                                if (n.clone() == None) {
                                    true
                                } else {
                                    (emit_map_has(param_name_set.clone(), n.clone().unwrap())
                                        == false)
                                }
                            } {
                                __result.push(arg);
                            }
                        }
                        __result
                    });
                    v1_rt::concat(ordered.clone(), leftovers.clone())
                }
            }
        }
    }
}

pub fn has_nested_records_node(
    mut n: Rc<Node>,
    mut source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    loop {
        let is_product = (n.connective.clone() == Connective::Conj);
        let is_coproduct = (n.connective.clone() == Connective::Disj);
        if is_product.clone() {
            break true;
        } else {
            if is_coproduct.clone() {
                let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
                if is_optional.clone() {
                    {
                        let __tco_0 = with_required_cardinality(n);
                        n = __tco_0;
                        continue;
                    }
                } else {
                    break false;
                }
            } else {
                let is_map = node_is_keyed_collection(n.clone(), source_indices.clone());
                if is_map.clone() {
                    match n.children.clone().get(1 as usize).cloned() {
                        Some(val_child) => {
                            let __tco_0 = child_type_node(val_child.clone());
                            n = __tco_0;
                            continue;
                        }
                        None => {
                            break false;
                        }
                    }
                } else {
                    if ((n.children.clone().len() as i64) == 1) {
                        match n.children.clone().first().cloned() {
                            Some(el) => {
                                let __tco_0 = child_type_node(el.clone());
                                n = __tco_0;
                                continue;
                            }
                            None => {
                                break false;
                            }
                        }
                    } else {
                        break false;
                    }
                }
            }
        }
    }
}

pub fn emit_data_value_json(
    value: Rc<Node>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*value.expr_data.clone()).clone() {
            ExprData::ExprLiteral { value: v, .. } => match (*v.clone()).clone() {
                LiteralValue::LitStr { value: s, .. } => v1_rt::concat(
                    v1_rt::concat("\"".to_string(), escape_json_string(s.clone())),
                    "\"".to_string(),
                ),
                LiteralValue::LitSymbol { value: s, .. } => v1_rt::concat(
                    v1_rt::concat("\"".to_string(), escape_json_string(s.clone())),
                    "\"".to_string(),
                ),
                LiteralValue::LitInt { value: i, .. } => (i.clone()).to_string(),
                LiteralValue::LitFloat { value: f, .. } => f.clone(),
                LiteralValue::LitBool { value: b, .. } => {
                    if b.clone() {
                        "true".to_string()
                    } else {
                        "false".to_string()
                    }
                }
                LiteralValue::LitNull => "null".to_string(),
            },
            ExprData::ExprListLit => {
                let el_strs = Rc::new({
                    let mut __result = Vec::new();
                    for e in value.children.clone().iter().cloned() {
                        __result.push(emit_data_value_json(e.clone(), source_indices.clone()));
                    }
                    __result
                });
                v1_rt::concat(
                    v1_rt::concat("[".to_string(), el_strs.clone().join(&", ".to_string())),
                    "]".to_string(),
                )
            }
            ExprData::ExprRecordLit { parent_enum: _, .. } => {
                let field_strs = Rc::new({
                    let mut __result = Vec::new();
                    for f in value.children.clone().iter().cloned() {
                        __result.push(v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    "\"".to_string(),
                                    escape_json_string(field_init_node_name_at(
                                        f.clone(),
                                        source_indices.clone(),
                                    )),
                                ),
                                "\": ".to_string(),
                            ),
                            emit_data_value_json(
                                field_init_node_value(f.clone()),
                                source_indices.clone(),
                            ),
                        ));
                    }
                    __result
                });
                v1_rt::concat(
                    v1_rt::concat("{".to_string(), field_strs.clone().join(&", ".to_string())),
                    "}".to_string(),
                )
            }
            ExprData::ExprVar {
                binding_kind: _, ..
            } => v1_rt::concat(
                v1_rt::concat(
                    "\"".to_string(),
                    escape_json_string(expr_var_name_at(value.clone(), source_indices.clone())),
                ),
                "\"".to_string(),
            ),
            ExprData::ExprUnaryOp {
                op: UnaryOpKind::Neg,
                ..
            } => v1_rt::concat(
                "-".to_string(),
                emit_data_value_json(unaryop_operand(value.clone()), source_indices.clone()),
            ),
            _ => "\"compile_error!(unsupported mock expression)\"".to_string(),
        }
    })
}

pub fn to_camel(name: String) -> String {
    {
        let parts = Rc::new(
            name.clone()
                .split(&"_".to_string())
                .map(|s| s.to_string())
                .collect::<Vec<_>>(),
        );
        if ((parts.clone().len() as i64) == 0) {
            name.clone()
        } else {
            {
                let first_part = match parts.clone().first().cloned() {
                    Some(p) => Rc::new({
                        let mut __result = Vec::new();
                        for c in Rc::new(p.clone().chars().map(|c| c as i64).collect::<Vec<_>>())
                            .iter()
                            .cloned()
                        {
                            __result.push(to_lower_char(c.clone()));
                        }
                        __result
                    })
                    .join(&"".to_string()),
                    None => "".to_string(),
                };
                let rest_parts = Rc::new({
                    let mut __result = Vec::new();
                    for pair in Rc::new({
                        let mut __result = Vec::new();
                        for pair in Rc::new(
                            parts
                                .clone()
                                .iter()
                                .cloned()
                                .enumerate()
                                .map(|(i, v)| (i as i64, v))
                                .collect::<Vec<_>>(),
                        )
                        .iter()
                        .cloned()
                        {
                            if (pair.0.clone() > 0) {
                                __result.push(pair);
                            }
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    {
                        __result.push(capitalize_first(pair.1.clone()));
                    }
                    __result
                });
                v1_rt::concat(first_part.clone(), rest_parts.clone().join(&"".to_string()))
            }
        }
    }
}

pub fn apply_naming_case(name: String, case_style: NamingCase) -> String {
    match case_style.clone() {
        NamingCase::PascalCase => {
            let parts = Rc::new(
                name.clone()
                    .split(&"_".to_string())
                    .map(|s| s.to_string())
                    .collect::<Vec<_>>(),
            );
            let pascal_parts = Rc::new({
                let mut __result = Vec::new();
                for p in parts.clone().iter().cloned() {
                    __result.push(capitalize_first(p.clone()));
                }
                __result
            });
            pascal_parts.clone().join(&"".to_string())
        }
        NamingCase::SnakeCase => to_snake(name.clone()),
        NamingCase::CamelCase => to_camel(name.clone()),
        NamingCase::AsAuthored => name.clone(),
    }
}

pub fn test_file_path(module_name: String, target: RenderTarget) -> String {
    {
        let conventions = test_conventions_for_target(target.clone());
        let file_dir = match conventions.file_dir.clone() {
            Some(dir) => dir.clone(),
            None => "".to_string(),
        };
        let filename = module_to_filename(module_name.clone());
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(file_dir.clone(), conventions.file_prefix.clone()),
                    filename.clone(),
                ),
                conventions.file_suffix.clone(),
            ),
            language_spec(target.clone())
                .scaffold
                .clone()
                .source_file_extension
                .clone(),
        )
    }
}

pub fn reserved_prefix(target: RenderTarget) -> String {
    match (*language_spec(target.clone())
        .reserved_words
        .clone()
        .strategy
        .clone())
    .clone()
    {
        ReservedWordStrategy::PrefixEscape { prefix: prefix, .. } => prefix.clone(),
        _ => "".to_string(),
    }
}

pub fn reserved_suffix(target: RenderTarget) -> String {
    match (*language_spec(target.clone())
        .reserved_words
        .clone()
        .strategy
        .clone())
    .clone()
    {
        ReservedWordStrategy::SuffixEscape { suffix: suffix, .. } => suffix.clone(),
        _ => "".to_string(),
    }
}

pub fn escape_rust_interp_text(s: String) -> String {
    {
        let escaped = Rc::new(
            escape_string_literal_body(s.clone())
                .split(&"{".to_string())
                .map(|s| s.to_string())
                .collect::<Vec<_>>(),
        )
        .join(&"{{".to_string());
        Rc::new(
            escaped
                .clone()
                .split(&"}".to_string())
                .map(|s| s.to_string())
                .collect::<Vec<_>>(),
        )
        .join(&"}}".to_string())
    }
}

pub fn escape_go_interp_text(s: String) -> String {
    Rc::new(
        escape_string_literal_body(s.clone())
            .split(&"%".to_string())
            .map(|s| s.to_string())
            .collect::<Vec<_>>(),
    )
    .join(&"%%".to_string())
}

