pub fn named_type_vars_in_inferred(inferred: Option<Rc<InferredNode>>) -> Rc<Vec<String>> {
    match inferred.clone().as_deref().cloned() {
        Some(InferredNode::TypeVariable { id: var_id, .. }) => Rc::new(vec![var_id.clone()]),
        Some(InferredNode::Resolved { node: rt, .. }) => named_type_vars_in_node(rt.clone()),
        _ => Rc::new(vec![]),
    }
}

pub fn named_type_vars_in_node(n: Rc<Node>) -> Rc<Vec<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let self_vars = named_type_vars_in_inferred(n.inferred.clone());
        let child_vars = Rc::new({
            let mut __result = Vec::new();
            for ch in n.children.clone().iter().cloned() {
                __result.extend((*named_type_vars_in_node(ch.clone())).iter().cloned());
            }
            __result
        });
        let param_vars = Rc::new({
            let mut __result = Vec::new();
            for p in n.params.clone().iter().cloned() {
                __result.extend(
                    (*named_type_vars_in_node(param_node_type_expr(p.clone())))
                        .iter()
                        .cloned(),
                );
            }
            __result
        });
        unique_strings(v1_rt::concat(
            v1_rt::concat(self_vars.clone(), child_vars.clone()),
            param_vars.clone(),
        ))
    })
}

pub fn render_named_type_base(
    n: Rc<Node>,
    target: RenderTarget,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let tn = authored_name_at(source_indices.clone(), n.clone());
        let base = coerce_primitive_type(target.clone(), tn.clone());
        let explicit_params = Rc::new({
            let mut __result = Vec::new();
            for p in n.params.clone().iter().cloned() {
                __result.push(render_node_type(
                    param_node_type_expr(p.clone()),
                    target.clone(),
                    v1_rt::rc_empty_set::<String>(),
                    source_indices.clone(),
                ));
            }
            __result
        });
        let inferred_params = if ((explicit_params.clone().len() as i64) == 0) {
            named_type_vars_in_node(n.clone())
        } else {
            Rc::new(vec![])
        };
        let param_names = v1_rt::concat(explicit_params.clone(), inferred_params.clone());
        if ((param_names.clone().len() as i64) == 0) {
            base
        } else {
            {
                let spec = language_spec(target.clone());
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(base, spec.type_arg_open.clone()),
                        param_names.clone().join(&", ".to_string()),
                    ),
                    spec.type_arg_close.clone(),
                )
            }
        }
    }
}

pub fn render_node_type(
    n: Rc<Node>,
    target: RenderTarget,
    shared_types: Rc<set<String>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let tn = authored_name_at(source_indices.clone(), n.clone());
        let n_is_error = if (n.inferred.clone() != None) {
            is_compiler_error(n.inferred.clone().clone().unwrap())
        } else {
            false
        };
        let n_is_type_var = if (n.inferred.clone() != None) {
            is_type_variable(n.inferred.clone().clone().unwrap())
        } else {
            false
        };
        if ((n_is_type_var.clone() || n_is_error.clone())
            && ((n.children.clone().len() as i64) == 0))
        {
            {
                let is_named_type_var = match n.inferred.clone().as_deref().cloned() {
                    Some(InferredNode::TypeVariable { id: var_id, .. }) => {
                        ((tn.clone() != "".to_string()) && (tn.clone() == var_id.clone()))
                    }
                    _ => false,
                };
                if (n_is_type_var.clone() && is_named_type_var.clone()) {
                    return coerce_primitive_type(target.clone(), tn.clone());
                }
                let label = if n_is_error.clone() {
                    "CompilerError".to_string()
                } else {
                    "TypeVariable".to_string()
                };
                let spec = language_spec(target.clone());
                let err_str = apply_type_template1(
                    spec.error_type_template.clone(),
                    v1_rt::concat("UNRESOLVED_".to_string(), label.clone()),
                );
                return err_str;
            }
        }
        let is_arrow = (n.connective.clone() == Connective::Arrow);
        if is_arrow.clone() {
            {
                let repr = target_callable(target.clone());
                let param_strs = Rc::new({
                    let mut __result = Vec::new();
                    for p in n.params.clone().iter().cloned() {
                        __result.push(render_node_type(
                            param_node_type_expr(p.clone()),
                            target.clone(),
                            shared_types.clone(),
                            source_indices.clone(),
                        ));
                    }
                    __result
                });
                let param_str = param_strs.clone().join(&repr.param_separator.clone());
                let ret_str = match n.inferred.clone().as_deref().cloned() {
                    Some(InferredNode::Resolved { node: rt, .. }) => render_node_type(
                        rt.clone(),
                        target.clone(),
                        shared_types.clone(),
                        source_indices.clone(),
                    ),
                    _ => language_spec(target.clone()).void_type.clone(),
                };
                let spec = language_spec(target.clone());
                let result = match spec.callable_type_template.clone() {
                    Some(t) => v1_rt::replace(
                        v1_rt::replace(t.clone(), "{params}".to_string(), param_str.clone()),
                        "{return}".to_string(),
                        ret_str.clone(),
                    ),
                    None => {
                        if (ret_str.clone() == "".to_string()) {
                            {
                                let void_template = v1_rt::replace(
                                    repr.template.clone(),
                                    v1_rt::concat(
                                        repr.return_separator.clone(),
                                        "{return}".to_string(),
                                    ),
                                    "".to_string(),
                                );
                                v1_rt::replace(
                                    void_template.clone(),
                                    "{params}".to_string(),
                                    param_str.clone(),
                                )
                            }
                        } else {
                            v1_rt::replace(
                                v1_rt::replace(
                                    repr.template.clone(),
                                    "{params}".to_string(),
                                    param_str.clone(),
                                ),
                                "{return}".to_string(),
                                ret_str.clone(),
                            )
                        }
                    }
                };
                return result;
            }
        }
        let is_optional = (n.return_cardinality.clone() == Cardinality::CardOptional);
        if is_optional.clone() {
            {
                let inner_str = render_node_type(
                    with_required_cardinality(n.clone()),
                    target.clone(),
                    shared_types.clone(),
                    source_indices.clone(),
                );
                let opt_str =
                    emit_container("optional".to_string(), inner_str.clone(), target.clone());
                return opt_str;
            }
        }
        let is_conj = (n.connective.clone() == Connective::Conj);
        let is_disj = (n.connective.clone() == Connective::Disj);
        let shared = v1_rt::set_contains(&shared_types, tn.clone());
        if is_disj.clone() {
            {
                let base = if (n.ident_span.clone() != None) {
                    render_named_type_base(n.clone(), target.clone(), source_indices.clone())
                } else {
                    {
                        let spec = language_spec(target.clone());
                        apply_type_template1(
                            spec.error_type_template.clone(),
                            "ANONYMOUS_COPRODUCT".to_string(),
                        )
                    }
                };
                let disj_str = if shared.clone() {
                    wrap_shared_type(target.clone(), base.clone())
                } else {
                    base.clone()
                };
                return disj_str;
            }
        }
        if is_conj.clone() {
            {
                if (n.type_annotation.clone() != None) {
                    {
                        let refined_str = match n.children.clone().first().cloned() {
                            Some(base) => render_node_type(
                                base.clone(),
                                target.clone(),
                                shared_types.clone(),
                                source_indices.clone(),
                            ),
                            None => coerce_primitive_type(target.clone(), "Refined".to_string()),
                        };
                        return refined_str;
                    }
                }
                let is_pair = (((n.connective.clone() == Connective::Conj)
                    && (n.ident_span.clone() == None))
                    && ((n.children.clone().len() as i64) == 2));
                if is_pair.clone() {
                    {
                        let first_child = match n.children.clone().first().cloned() {
                            Some(c) => {
                                if (c.inferred.clone() != None) {
                                    render_node_type(
                                        resolved_type(c.clone()),
                                        target.clone(),
                                        shared_types.clone(),
                                        source_indices.clone(),
                                    )
                                } else {
                                    render_node_type(
                                        c.clone(),
                                        target.clone(),
                                        shared_types.clone(),
                                        source_indices.clone(),
                                    )
                                }
                            }
                            None => "_".to_string(),
                        };
                        let second_child = match n.children.clone().get(1 as usize).cloned() {
                            Some(c) => {
                                if (c.inferred.clone() != None) {
                                    render_node_type(
                                        resolved_type(c.clone()),
                                        target.clone(),
                                        shared_types.clone(),
                                        source_indices.clone(),
                                    )
                                } else {
                                    render_node_type(
                                        c.clone(),
                                        target.clone(),
                                        shared_types.clone(),
                                        source_indices.clone(),
                                    )
                                }
                            }
                            None => "_".to_string(),
                        };
                        let tuple_str = render_tuple_parts(
                            Rc::new(vec![first_child.clone(), second_child.clone()]),
                            target.clone(),
                        );
                        return tuple_str;
                    }
                }
                if (n.ident_span.clone() != None) {
                    {
                        let snake = to_snake(tn.clone());
                        let has_template = match container_template_algebra(snake.clone()) {
                            Some(_) => true,
                            None => false,
                        };
                        if has_template.clone() {
                            {
                                let base = if (snake.clone() == "map".to_string()) {
                                    emit_map_type("_".to_string(), "_".to_string(), target.clone())
                                } else {
                                    emit_container(snake.clone(), "_".to_string(), target.clone())
                                };
                                let conj_container_str = if shared.clone() {
                                    wrap_shared_type(target.clone(), base.clone())
                                } else {
                                    base.clone()
                                };
                                return conj_container_str;
                            }
                        }
                        let base = render_named_type_base(
                            n.clone(),
                            target.clone(),
                            source_indices.clone(),
                        );
                        let conj_named_str = if shared.clone() {
                            wrap_shared_type(target.clone(), base.clone())
                        } else {
                            base.clone()
                        };
                        return conj_named_str;
                    }
                }
                let parts = Rc::new({
                    let mut __result = Vec::new();
                    for child in n.children.clone().iter().cloned() {
                        __result.push(render_node_type(
                            resolved_type(child.clone()),
                            target.clone(),
                            shared_types.clone(),
                            source_indices.clone(),
                        ));
                    }
                    __result
                });
                let anon_str = render_tuple_parts(parts.clone(), target.clone());
                return anon_str;
            }
        }
        if ((n.children.clone().len() as i64) == 0) {
            {
                let bare_is_map =
                    (is_container_type(tn.clone()) && (to_snake(tn.clone()) == "map".to_string()));
                let bare_is_collection =
                    (is_declared_container_alias_spelling(tn.clone()) && !bare_is_map.clone());
                let has_container_template = match container_template_algebra(to_snake(tn.clone()))
                {
                    Some(_) => true,
                    None => false,
                };
                let param_count = (n.params.clone().len() as i64);
                let base = if bare_is_map.clone() {
                    emit_map_type("_".to_string(), "_".to_string(), target.clone())
                } else {
                    if bare_is_collection.clone() {
                        emit_container(to_snake(tn.clone()), "_".to_string(), target.clone())
                    } else {
                        if (has_container_template.clone() && (param_count.clone() == 1)) {
                            {
                                let inner = match n.params.clone().first().cloned() {
                                    Some(p) => render_node_type(
                                        param_node_type_expr(p.clone()),
                                        target.clone(),
                                        shared_types.clone(),
                                        source_indices.clone(),
                                    ),
                                    None => "_".to_string(),
                                };
                                emit_container(to_snake(tn.clone()), inner.clone(), target.clone())
                            }
                        } else {
                            if (param_count.clone() > 0) {
                                {
                                    let param_strs = Rc::new({
                                        let mut __result = Vec::new();
                                        for p in n.params.clone().iter().cloned() {
                                            __result.push(render_node_type(
                                                param_node_type_expr(p.clone()),
                                                target.clone(),
                                                shared_types.clone(),
                                                source_indices.clone(),
                                            ));
                                        }
                                        __result
                                    });
                                    let spec = language_spec(target.clone());
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                coerce_primitive_type(target.clone(), tn.clone()),
                                                spec.type_arg_open.clone(),
                                            ),
                                            param_strs.clone().join(&", ".to_string()),
                                        ),
                                        spec.type_arg_close.clone(),
                                    )
                                }
                            } else {
                                if (tn.clone() == tuple_type_name()) {
                                    render_tuple_parts(Rc::new(vec![]), target.clone())
                                } else {
                                    coerce_primitive_type(target.clone(), tn.clone())
                                }
                            }
                        }
                    }
                };
                let bare_str = if shared.clone() {
                    wrap_shared_type(target.clone(), base.clone())
                } else {
                    base.clone()
                };
                return bare_str;
            }
        }
        let is_map = node_is_keyed_collection(n.clone(), source_indices.clone());
        if is_map.clone() {
            {
                let k = match n.children.clone().first().cloned() {
                    Some(kn) => render_node_type(
                        child_type_node(kn.clone()),
                        target.clone(),
                        shared_types.clone(),
                        source_indices.clone(),
                    ),
                    None => "_".to_string(),
                };
                let v = match n.children.clone().get(1 as usize).cloned() {
                    Some(vn) => render_node_type(
                        child_type_node(vn.clone()),
                        target.clone(),
                        shared_types.clone(),
                        source_indices.clone(),
                    ),
                    None => "_".to_string(),
                };
                let base = emit_map_type(k.clone(), v.clone(), target.clone());
                let map_str = if shared.clone() {
                    wrap_shared_type(target.clone(), base.clone())
                } else {
                    base.clone()
                };
                return map_str;
            }
        }
        if ((n.children.clone().len() as i64) == 1) {
            {
                let child_str = match n.children.clone().first().cloned() {
                    Some(child) => render_node_type(
                        child_type_node(child.clone()),
                        target.clone(),
                        shared_types.clone(),
                        source_indices.clone(),
                    ),
                    None => "_".to_string(),
                };
                let is_container = node_is_collection(n.clone(), source_indices.clone());
                let base = if is_container.clone() {
                    emit_container(to_snake(tn.clone()), child_str.clone(), target.clone())
                } else {
                    {
                        let type_base = coerce_primitive_type(target.clone(), tn.clone());
                        let spec = language_spec(target.clone());
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(type_base.clone(), spec.type_arg_open.clone()),
                                child_str.clone(),
                            ),
                            spec.type_arg_close.clone(),
                        )
                    }
                };
                let single_str = if shared.clone() {
                    wrap_shared_type(target.clone(), base.clone())
                } else {
                    base.clone()
                };
                return single_str;
            }
        }
        let child_strs = Rc::new({
            let mut __result = Vec::new();
            for c in n.children.clone().iter().cloned() {
                __result.push(render_node_type(
                    child_type_node(c.clone()),
                    target.clone(),
                    shared_types.clone(),
                    source_indices.clone(),
                ));
            }
            __result
        });
        if (tn.clone() == tuple_type_name()) {
            {
                let multi_tuple_str = render_tuple_parts(child_strs.clone(), target.clone());
                return multi_tuple_str;
            }
        }
        let type_base = coerce_primitive_type(target.clone(), tn.clone());
        let args_joined = child_strs.clone().join(&", ".to_string());
        let spec = language_spec(target.clone());
        let base = v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(type_base.clone(), spec.type_arg_open.clone()),
                args_joined.clone(),
            ),
            spec.type_arg_close.clone(),
        );
        if shared.clone() {
            wrap_shared_type(target.clone(), base.clone())
        } else {
            base.clone()
        }
    })
}

pub fn render_tuple_parts(parts: Rc<Vec<String>>, target: RenderTarget) -> String {
    {
        let spec = language_spec(target.clone());
        let ts = spec.tuple_syntax.clone();
        if ((parts.clone().len() as i64) > 0) {
            if ((parts.clone().len() as i64) == 2) {
                match parts.clone().first().cloned() {
                    Some(p0) => match parts.clone().get(1 as usize).cloned() {
                        Some(p1) => {
                            apply_type_template2(ts.pair_template.clone(), p0.clone(), p1.clone())
                        }
                        None => apply_type_template1(
                            ts.multi_template.clone(),
                            parts.clone().join(&ts.separator.clone()),
                        ),
                    },
                    None => apply_type_template1(
                        ts.multi_template.clone(),
                        parts.clone().join(&ts.separator.clone()),
                    ),
                }
            } else {
                apply_type_template1(
                    ts.multi_template.clone(),
                    parts.clone().join(&ts.separator.clone()),
                )
            }
        } else {
            ts.empty.clone()
        }
    }
}

pub fn has_service_items(typed: Rc<ResolvedGraph>) -> bool {
    {
        let mut __found = false;
        for tm in typed.modules.clone().iter().cloned() {
            if {
                let mut __found = false;
                for item in tm.items.clone().iter().cloned() {
                    if is_service_item(item.clone()) {
                        __found = true;
                        break;
                    }
                }
                __found
            } {
                __found = true;
                break;
            }
        }
        __found
    }
}

pub fn service_fallback_transport(item: Rc<Node>) -> Rc<Node> {
    if (item.transport.clone() == None) {
        local_transport_node(item.span.clone())
    } else {
        item.transport.clone().clone().unwrap()
    }
}

pub fn effective_operation_transport(op_node: Rc<Node>, fallback: Rc<Node>) -> Rc<Node> {
    match op_node.transport.clone() {
        Some(op_transport) => op_transport.clone(),
        None => fallback,
    }
}

pub fn service_has_rest(
    fallback_transport: Rc<Node>,
    op_children: Rc<Vec<Rc<Node>>>,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    {
        let from_fallback = is_rest_transport(fallback_transport.clone(), source_indices.clone());
        let from_ops = {
            let mut __found = false;
            for op in op_children.clone().iter().cloned() {
                if if (op.transport.clone() != None) {
                    is_rest_transport(
                        op.transport.clone().clone().unwrap(),
                        source_indices.clone(),
                    )
                } else {
                    false
                } {
                    __found = true;
                    break;
                }
            }
            __found
        };
        (from_fallback.clone() || from_ops.clone())
    }
}

