pub fn emit_typed_string_interp_unified(
    parts: Rc<Vec<Rc<StringPart>>>,
    target: RenderTarget,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let spec = language_spec(target.clone());
        let interp = spec.string_interp.clone();
        let has_interpolations = {
            let mut __found = false;
            for p in parts.clone().iter().cloned() {
                if match (*p.clone()).clone() {
                    StringPart::Interpolation { expr: _, .. } => true,
                    _ => false,
                } {
                    __found = true;
                    break;
                }
            }
            __found
        };
        match (*interp.style.clone()).clone() {
            InterpStyle::FormatArgs {
                placeholder: ph, ..
            } => {
                let fmt_parts = Rc::new({
                    let mut __result = Vec::new();
                    for p in parts.clone().iter().cloned() {
                        __result.push(match (*p.clone()).clone() {
                            StringPart::Text { value: v, .. } => {
                                let base = escape_string_literal_body(v.clone());
                                let escaped = if has_interpolations.clone() {
                                    apply_escape_pairs(base.clone(), interp.escape_pairs.clone())
                                } else {
                                    base.clone()
                                };
                                Rc::new(InterpPart {
                                    format_segment: escaped.clone(),
                                    arg_expr: "".to_string(),
                                })
                            }
                            StringPart::Interpolation { expr: e, .. } => Rc::new(InterpPart {
                                format_segment: ph.clone(),
                                arg_expr: recurse(e.clone()),
                            }),
                        });
                    }
                    __result
                });
                let fmt_str = Rc::new({
                    let mut __result = Vec::new();
                    for p in fmt_parts.clone().iter().cloned() {
                        __result.push(p.format_segment.clone());
                    }
                    __result
                })
                .join(&"".to_string());
                let args = Rc::new({
                    let mut __result = Vec::new();
                    for a in Rc::new({
                        let mut __result = Vec::new();
                        for p in fmt_parts.clone().iter().cloned() {
                            __result.push(p.arg_expr.clone());
                        }
                        __result
                    })
                    .iter()
                    .cloned()
                    {
                        if (a.clone() != "".to_string()) {
                            __result.push(a);
                        }
                    }
                    __result
                });
                if ((args.clone().len() as i64) == 0) {
                    apply_type_template1(interp.plain_template.clone(), fmt_str.clone())
                } else {
                    {
                        let args_str = args.clone().join(&", ".to_string());
                        apply_type_template2(
                            interp.format_template.clone(),
                            fmt_str.clone(),
                            args_str.clone(),
                        )
                    }
                }
            }
            InterpStyle::InlineExpr => {
                let segments = Rc::new({
                    let mut __result = Vec::new();
                    for p in parts.clone().iter().cloned() {
                        __result.push(match (*p.clone()).clone() {
                            StringPart::Text { value: v, .. } => {
                                let base = escape_string_literal_body(v.clone());
                                if has_interpolations.clone() {
                                    apply_escape_pairs(base.clone(), interp.escape_pairs.clone())
                                } else {
                                    base.clone()
                                }
                            }
                            StringPart::Interpolation { expr: e, .. } => v1_rt::concat(
                                v1_rt::concat("{".to_string(), recurse(e.clone())),
                                "}".to_string(),
                            ),
                        });
                    }
                    __result
                });
                apply_type_template1(
                    interp.format_template.clone(),
                    segments.clone().join(&"".to_string()),
                )
            }
        }
    }
}

pub fn emit_typed_record_lit_unified(
    type_name: Option<String>,
    fields: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let rls = language_spec(target.clone()).record_lit.clone();
        match type_name.clone() {
            None => {
                if ((fields.clone().len() as i64) == 0) {
                    rls.anon_empty.clone()
                } else {
                    {
                        let field_strs = Rc::new({
                            let mut __result = Vec::new();
                            for f in fields.clone().iter().cloned() {
                                __result.push(v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(
                                                    rls.anon_field_indent.clone(),
                                                    "\"".to_string(),
                                                ),
                                                field_init_node_name_at(
                                                    f.clone(),
                                                    source_indices.clone(),
                                                ),
                                            ),
                                            "\": ".to_string(),
                                        ),
                                        recurse(field_init_node_value(f.clone())),
                                    ),
                                    ",".to_string(),
                                ));
                            }
                            __result
                        });
                        let fields_str = field_strs.clone().join(&"\n".to_string());
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(rls.anon_prefix.clone(), fields_str.clone()),
                                "\n".to_string(),
                            ),
                            rls.anon_suffix.clone(),
                        )
                    }
                }
            }
            Some(tn) => {
                if ((fields.clone().len() as i64) == 0) {
                    v1_rt::concat(tn.clone(), rls.named_empty.clone())
                } else {
                    {
                        let field_strs = Rc::new({
                            let mut __result = Vec::new();
                            for f in fields.clone().iter().cloned() {
                                __result.push(v1_rt::concat(
                                    v1_rt::concat(
                                        emit_export_ident(
                                            field_init_node_name_at(
                                                f.clone(),
                                                source_indices.clone(),
                                            ),
                                            target.clone(),
                                        ),
                                        rls.named_field_sep.clone(),
                                    ),
                                    recurse(field_init_node_value(f.clone())),
                                ));
                            }
                            __result
                        });
                        let fields_str = field_strs.clone().join(&rls.named_field_join.clone());
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(tn.clone(), rls.named_open.clone()),
                                fields_str.clone(),
                            ),
                            rls.named_close.clone(),
                        )
                    }
                }
            }
        }
    }
}

pub fn is_go_v2rt_free_function(name: String) -> bool {
    match name.clone().as_str() {
        "concat" => true,
        "to_string" => true,
        "lookup" => true,
        _ => false,
    }
}

pub fn emit_go_v2rt_free_call(func: String, arg_strs: Rc<Vec<String>>) -> String {
    v1_rt::concat(
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    "v2rt.".to_string(),
                    emit_export_ident(
                        bridge_method_name_unified(func.clone(), RenderTarget::Go),
                        RenderTarget::Go,
                    ),
                ),
                "(".to_string(),
            ),
            arg_strs.clone().join(&", ".to_string()),
        ),
        ")".to_string(),
    )
}

pub fn emit_typed_call_unified(
    func: String,
    args: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let spec = language_spec(target.clone());
        let ordered_args = order_typed_call_args(args.clone(), func.clone(), scope.clone());
        let arg_strs = Rc::new({
            let mut __result = Vec::new();
            for a in ordered_args.clone().iter().cloned() {
                __result.push(recurse(arg_value(a.clone())));
            }
            __result
        });
        let callee = lookup_item(registry.clone(), func.clone());
        let extra_args = match callee.clone() {
            Some(info) => {
                let has_effects = (((info.service_names.clone().len() as i64) > 0)
                    || ((info.resource_names.clone().len() as i64) > 0));
                if has_effects.clone() {
                    {
                        let resource_args = Rc::new({
                            let mut __result = Vec::new();
                            for rn in info.resource_names.clone().iter().cloned() {
                                __result.push(emit_ident(rn.clone(), target.clone()));
                            }
                            __result
                        });
                        let service_args = Rc::new({
                            let mut __result = Vec::new();
                            for sn in info.service_names.clone().iter().cloned() {
                                __result.push(service_var_name(sn.clone()));
                            }
                            __result
                        });
                        v1_rt::concat(resource_args.clone(), service_args.clone())
                    }
                } else {
                    Rc::new(vec![])
                }
            }
            None => Rc::new(vec![]),
        };
        let all_args = v1_rt::concat(arg_strs.clone(), extra_args.clone());
        let args_str = all_args.clone().join(&", ".to_string());
        let call_str = match target.clone() {
            RenderTarget::Go => {
                if is_go_v2rt_free_function(func.clone()) {
                    emit_go_v2rt_free_call(func.clone(), all_args.clone())
                } else {
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                emit_export_ident(func.clone(), target.clone()),
                                "(".to_string(),
                            ),
                            args_str.clone(),
                        ),
                        ")".to_string(),
                    )
                }
            }
            _ => v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        emit_export_ident(func.clone(), target.clone()),
                        "(".to_string(),
                    ),
                    args_str.clone(),
                ),
                ")".to_string(),
            ),
        };
        match callee.clone() {
            Some(info) => {
                let has_effects = (((info.service_names.clone().len() as i64) > 0)
                    || ((info.resource_names.clone().len() as i64) > 0));
                if has_effects.clone() {
                    v1_rt::concat(spec.async_call_prefix.clone(), call_str.clone())
                } else {
                    call_str.clone()
                }
            }
            None => call_str.clone(),
        }
    }
}

pub fn bridge_method_name_unified(method_name: String, target: RenderTarget) -> String {
    {
        let spec = language_spec(target.clone());
        let overridden = apply_bridge_method_overrides(
            method_name.clone(),
            spec.bridge_method_overrides.clone(),
        );
        apply_naming_case(overridden.clone(), spec.bridge_method_case.clone())
    }
}

pub fn emit_algebra_method_call_unified(
    method_name: String,
    receiver: Rc<Node>,
    args: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    first_arg_str: String,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let spec = language_spec(target.clone());
        let recv_str = recurse(receiver.clone());
        match emit_algebra_method_template(
            method_name.clone(),
            recv_str.clone(),
            first_arg_str.clone(),
            target.clone(),
        ) {
            Some(result) => result.clone(),
            None => {
                let function_name = bridge_method_name_unified(method_name.clone(), target.clone());
                let arg_strs = Rc::new({
                    let mut __result = Vec::new();
                    for a in args.clone().iter().cloned() {
                        __result.push(recurse(arg_value(a.clone())));
                    }
                    __result
                });
                let all_args = v1_rt::concat(Rc::new(vec![recv_str.clone()]), arg_strs.clone());
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                spec.bridge_method_prefix.clone(),
                                emit_export_ident(function_name.clone(), target.clone()),
                            ),
                            "(".to_string(),
                        ),
                        all_args.clone().join(&", ".to_string()),
                    ),
                    ")".to_string(),
                )
            }
        }
    }
}

pub fn emit_plain_method_call_unified(
    receiver: Rc<Node>,
    method: String,
    args: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let recv_str = recurse(receiver.clone());
        let arg_strs = Rc::new({
            let mut __result = Vec::new();
            for a in args.clone().iter().cloned() {
                __result.push(recurse(arg_value(a.clone())));
            }
            __result
        });
        let args_str = arg_strs.clone().join(&", ".to_string());
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(recv_str.clone(), ".".to_string()),
                        emit_export_ident(method.clone(), target.clone()),
                    ),
                    "(".to_string(),
                ),
                args_str.clone(),
            ),
            ")".to_string(),
        )
    }
}

pub fn emit_typed_method_call_unified(
    receiver: Rc<Node>,
    method: String,
    args: Rc<Vec<Rc<Node>>>,
    method_semantics: Option<Rc<MethodSemantics>>,
    target: RenderTarget,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let spec = language_spec(target.clone());
        let source_indices = scope.type_env.clone().source_indices.clone();
        if (method_semantics.clone() != None) {
            match (*method_semantics.clone().unwrap()).clone() {
                MethodSemantics::ServiceMethodSemantics {
                    service_name: svc_name,
                    ..
                } => {
                    let var_name = service_var_name(svc_name.clone());
                    let arg_strs = Rc::new({
                        let mut __result = Vec::new();
                        for a in args.clone().iter().cloned() {
                            __result.push(recurse(arg_value(a.clone())));
                        }
                        __result
                    });
                    let args_str = arg_strs.clone().join(&", ".to_string());
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            spec.async_call_prefix.clone(),
                                            var_name.clone(),
                                        ),
                                        ".".to_string(),
                                    ),
                                    emit_export_ident(method.clone(), target.clone()),
                                ),
                                "(".to_string(),
                            ),
                            args_str.clone(),
                        ),
                        ")".to_string(),
                    )
                }
                MethodSemantics::AlgebraMethodSemantics { method_def, .. } => {
                    let mn = authored_name_at(source_indices.clone(), method_def.clone());
                    let first_arg_str =
                        emit_typed_first_arg_shared(args.clone(), target.clone(), recurse.clone());
                    emit_algebra_method_call_unified(
                        mn.clone(),
                        receiver.clone(),
                        args.clone(),
                        target.clone(),
                        first_arg_str.clone(),
                        recurse.clone(),
                    )
                }
                MethodSemantics::PlainMethodSemantics => emit_plain_method_call_unified(
                    receiver.clone(),
                    method.clone(),
                    args.clone(),
                    target.clone(),
                    recurse.clone(),
                ),
            }
        } else {
            if is_typed_service_call_receiver(receiver.clone(), source_indices.clone()) {
                match extract_typed_service_name(receiver.clone(), source_indices.clone()) {
                    Some(svc_name) => {
                        let var_name = service_var_name(svc_name.clone());
                        let arg_strs = Rc::new({
                            let mut __result = Vec::new();
                            for a in args.clone().iter().cloned() {
                                __result.push(recurse(arg_value(a.clone())));
                            }
                            __result
                        });
                        let args_str = arg_strs.clone().join(&", ".to_string());
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                spec.async_call_prefix.clone(),
                                                var_name.clone(),
                                            ),
                                            ".".to_string(),
                                        ),
                                        emit_export_ident(method.clone(), target.clone()),
                                    ),
                                    "(".to_string(),
                                ),
                                args_str.clone(),
                            ),
                            ")".to_string(),
                        )
                    }
                    None => {
                        emit_error_expr("unsupported service receiver".to_string(), target.clone())
                    }
                }
            } else {
                emit_plain_method_call_unified(
                    receiver.clone(),
                    method.clone(),
                    args.clone(),
                    target.clone(),
                    recurse.clone(),
                )
            }
        }
    }
}

pub fn emit_unified_pattern(
    pattern: Rc<MatchPattern>,
    target: RenderTarget,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match (*pattern.clone()).clone() {
        MatchPattern::Bind { name: n, .. } => emit_ident(n.clone(), target.clone()),
        MatchPattern::LitPattern { value: v, .. } => emit_literal(v.clone(), target.clone()),
        MatchPattern::VariantPattern {
            name: n,
            parent_enum: pe,
            field_bindings: fbs,
            ..
        } => emit_unified_variant_pattern(
            n.clone(),
            pe.clone(),
            fbs.clone(),
            target.clone(),
            source_indices.clone(),
        ),
        MatchPattern::Wildcard => "_".to_string(),
    }
}

pub fn go_variant_case_type(name: String, parent_enum: Option<String>) -> String {
    match parent_enum.clone() {
        Some(parent) => v1_rt::concat(parent.clone(), name.clone()),
        None => name.clone(),
    }
}

pub fn emit_unified_variant_pattern(
    name: String,
    parent_enum: Option<String>,
    field_bindings: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let es = language_spec(target.clone()).expression_semantics.clone();
        match es.variant_pattern.clone() {
            Some(vps) => {
                if ((field_bindings.clone().len() as i64) == 0) {
                    v1_rt::concat(name.clone(), vps.empty_suffix.clone())
                } else {
                    {
                        let binding_strs = Rc::new({
                            let mut __result = Vec::new();
                            for fb in field_bindings.clone().iter().cloned() {
                                __result.push({
                                    let pat_str = emit_unified_pattern(
                                        field_binding_pattern(fb.clone()),
                                        target.clone(),
                                        source_indices.clone(),
                                    );
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            emit_ident(
                                                field_binding_name_at(
                                                    fb.clone(),
                                                    source_indices.clone(),
                                                ),
                                                target.clone(),
                                            ),
                                            vps.binding_sep.clone(),
                                        ),
                                        pat_str.clone(),
                                    )
                                });
                            }
                            __result
                        });
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(name.clone(), vps.open.clone()),
                                binding_strs.clone().join(&", ".to_string()),
                            ),
                            vps.close.clone(),
                        )
                    }
                }
            }
            None => match target.clone() {
                RenderTarget::Go => go_variant_case_type(name.clone(), parent_enum.clone()),
                _ => {
                    if ((field_bindings.clone().len() as i64) > 0) {
                        emit_error_expr("variant patterns with field bindings are not supported for this target".to_string(), target.clone())
                    } else {
                        go_variant_case_type(name.clone(), parent_enum.clone())
                    }
                }
            },
        }
    }
}

pub fn emit_match_arm_body_stmt(target: RenderTarget, body_str: String) -> String {
    match language_spec(target.clone())
        .expression_semantics
        .clone()
        .match_value_form
        .clone()
    {
        MatchValueForm::MatchStatementArmReturn => {
            v1_rt::concat("return ".to_string(), body_str.clone())
        }
        MatchValueForm::MatchExpression => body_str.clone(),
    }
}

pub fn emit_match_arm_line(
    arm: Rc<Node>,
    target: RenderTarget,
    case_depth: i64,
    body_depth: i64,
    body_str: String,
    guard_str: String,
    render_pattern: impl Fn(Rc<MatchPattern>) -> String + Clone,
) -> String {
    {
        let spec = language_spec(target.clone());
        let bs = spec.block_syntax.clone();
        let es = spec.expression_semantics.clone();
        let pat = arm_pattern(arm.clone());
        let case_kw = match (*pat.clone()).clone() {
            MatchPattern::Wildcard => match es.wildcard_case.clone() {
                Some(wc) => wc.clone(),
                None => v1_rt::concat(bs.case_keyword.clone(), render_pattern(pat.clone())),
            },
            _ => v1_rt::concat(bs.case_keyword.clone(), render_pattern(pat.clone())),
        };
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(make_indent(case_depth.clone()), case_kw.clone()),
                        guard_str.clone(),
                    ),
                    ":\n".to_string(),
                ),
                make_indent(body_depth.clone()),
            ),
            body_str.clone(),
        )
    }
}

pub fn emit_arm_guard(
    arm: Rc<Node>,
    target: RenderTarget,
    render_guard_expr: impl Fn(Rc<Node>) -> String + Clone,
) -> String {
    {
        let es = language_spec(target.clone()).expression_semantics.clone();
        match arm_guard(arm.clone()) {
            Some(g) => match es.guard_prefix.clone() {
                Some(prefix) => v1_rt::concat(prefix.clone(), render_guard_expr(g.clone())),
                None => emit_error_expr(
                    "target does not support pattern guards".to_string(),
                    target.clone(),
                ),
            },
            None => "".to_string(),
        }
    }
}

pub fn emit_go_match_arm_bindings(
    arm: Rc<Node>,
    indent_level: i64,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match (*arm_pattern(arm.clone())).clone() {
        MatchPattern::VariantPattern {
            field_bindings: fbs,
            ..
        } => {
            if ((fbs.clone().len() as i64) == 0) {
                "".to_string()
            } else {
                Rc::new({
                    let mut __result = Vec::new();
                    for fb in fbs.clone().iter().cloned() {
                        __result.push(v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(
                                        make_indent(indent_level.clone()),
                                        emit_ident(
                                            field_binding_name_at(
                                                fb.clone(),
                                                source_indices.clone(),
                                            ),
                                            RenderTarget::Go,
                                        ),
                                    ),
                                    " := __gunbcMatch.".to_string(),
                                ),
                                emit_export_ident(
                                    field_binding_name_at(fb.clone(), source_indices.clone()),
                                    RenderTarget::Go,
                                ),
                            ),
                            "\n".to_string(),
                        ));
                    }
                    __result
                })
                .join(&"".to_string())
            }
        }
        _ => "".to_string(),
    }
}

pub fn emit_typed_match_go(
    scrutinee_str: String,
    arms: Rc<Vec<Rc<Node>>>,
    depth: i64,
    recurse: impl Fn(Rc<Node>, i64) -> String + Clone,
    render_pattern: impl Fn(Rc<MatchPattern>) -> String + Clone,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let bs = language_spec(RenderTarget::Go).block_syntax.clone();
        let case_depth = (depth.clone() + 1);
        let body_depth = (case_depth.clone() + 1);
        let arm_strs = Rc::new({
            let mut __result = Vec::new();
            for arm in arms.clone().iter().cloned() {
                __result.push({
                    let bindings = emit_go_match_arm_bindings(
                        arm.clone(),
                        body_depth.clone(),
                        source_indices.clone(),
                    );
                    let body_str = emit_match_arm_body_stmt(
                        RenderTarget::Go,
                        recurse(arm_body(arm.clone()), body_depth.clone()),
                    );
                    let guard_str = emit_arm_guard(arm.clone(), RenderTarget::Go, |g| {
                        recurse(g.clone(), depth.clone())
                    });
                    emit_match_arm_line(
                        arm.clone(),
                        RenderTarget::Go,
                        case_depth.clone(),
                        body_depth.clone(),
                        v1_rt::concat(bindings.clone(), body_str.clone()),
                        guard_str.clone(),
                        render_pattern.clone(),
                    )
                });
            }
            __result
        });
        v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    "switch __gunbcMatch := ".to_string(),
                                    scrutinee_str.clone(),
                                ),
                                ".(type)".to_string(),
                            ),
                            bs.block_open.clone(),
                        ),
                        arm_strs.clone().join(&"\n".to_string()),
                    ),
                    "\n".to_string(),
                ),
                make_indent(depth.clone()),
            ),
            bs.block_close.clone(),
        )
    }
}

pub fn emit_typed_match_unified(
    scrutinee_str: String,
    arms: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    depth: i64,
    recurse: impl Fn(Rc<Node>, i64) -> String + Clone,
    render_pattern: impl Fn(Rc<MatchPattern>) -> String + Clone,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    match target.clone() {
        RenderTarget::Go => emit_typed_match_go(
            scrutinee_str.clone(),
            arms.clone(),
            depth.clone(),
            recurse.clone(),
            render_pattern.clone(),
            source_indices.clone(),
        ),
        _ => {
            let bs = language_spec(target.clone()).block_syntax.clone();
            let case_depth = if bs.significant_whitespace.clone() {
                (depth.clone() + 1)
            } else {
                depth.clone()
            };
            let body_depth = (case_depth.clone() + 1);
            let arm_strs = Rc::new({
                let mut __result = Vec::new();
                for arm in arms.clone().iter().cloned() {
                    __result.push({
                        let body_str = emit_match_arm_body_stmt(
                            target.clone(),
                            recurse(arm_body(arm.clone()), body_depth.clone()),
                        );
                        let guard_str = emit_arm_guard(arm.clone(), target.clone(), |g| {
                            recurse(g.clone(), depth.clone())
                        });
                        emit_match_arm_line(
                            arm.clone(),
                            target.clone(),
                            case_depth.clone(),
                            body_depth.clone(),
                            body_str.clone(),
                            guard_str.clone(),
                            render_pattern.clone(),
                        )
                    });
                }
                __result
            });
            let arms_str = arm_strs.clone().join(&"\n".to_string());
            if (bs.block_close.clone() == "".to_string()) {
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(bs.match_keyword.clone(), scrutinee_str.clone()),
                        bs.block_open.clone(),
                    ),
                    arms_str.clone(),
                )
            } else {
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat(
                            v1_rt::concat(
                                v1_rt::concat(
                                    v1_rt::concat(bs.match_keyword.clone(), scrutinee_str.clone()),
                                    bs.block_open.clone(),
                                ),
                                arms_str.clone(),
                            ),
                            "\n".to_string(),
                        ),
                        make_indent(depth.clone()),
                    ),
                    bs.block_close.clone(),
                )
            }
        }
    }
}

pub fn emit_field_access_unified(
    base_str: String,
    field: String,
    summary: Option<Rc<FieldSummary>>,
    target: RenderTarget,
) -> String {
    {
        let ts = language_spec(target.clone()).tuple_syntax.clone();
        match summary.clone() {
            Some(fs) => match fs.access_style.clone() {
                FieldAccessStyle::TupleFirst => {
                    v1_rt::concat(base_str.clone(), ts.first_accessor.clone())
                }
                FieldAccessStyle::TupleSecond => {
                    v1_rt::concat(base_str.clone(), ts.second_accessor.clone())
                }
                _ => v1_rt::concat(
                    v1_rt::concat(base_str.clone(), ".".to_string()),
                    emit_export_ident(field.clone(), target.clone()),
                ),
            },
            None => v1_rt::concat(
                v1_rt::concat(base_str.clone(), ".".to_string()),
                emit_export_ident(field.clone(), target.clone()),
            ),
        }
    }
}

pub fn emit_unified_typed_expr(
    texpr: Rc<Node>,
    target: RenderTarget,
    registry: Rc<HashMap<String, Rc<ItemInfo>>>,
    scope: Rc<InferScope>,
    depth: i64,
    fuel: i64,
    render_pattern: impl Fn(Rc<MatchPattern>) -> String + Clone,
) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let si = scope.type_env.clone().source_indices.clone();
        let spec = language_spec(target.clone());
        emit_shared_expr(
            texpr.clone(),
            target.clone(),
            si.clone(),
            |result| result.clone(),
            |child| {
                emit_unified_typed_expr(
                    child.clone(),
                    target.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    (fuel.clone() - 1),
                    render_pattern.clone(),
                )
            },
            |expr| emit_expr_var_shared(expr.clone(), target.clone(), si.clone()),
            |expr| {
                let fa_si = scope.type_env.clone().source_indices.clone();
                if is_typed_service_call_receiver(expr.clone(), fa_si.clone()) {
                    match extract_typed_service_name(expr.clone(), fa_si.clone()) {
                        Some(svc_name) => service_var_name(svc_name.clone()),
                        None => {
                            let base_str = emit_unified_typed_expr(
                                field_access_base(expr.clone()),
                                target.clone(),
                                registry.clone(),
                                scope.clone(),
                                depth.clone(),
                                1024,
                                render_pattern.clone(),
                            );
                            emit_field_access_unified(
                                base_str.clone(),
                                field_access_field_at(expr.clone(), fa_si.clone()),
                                expr_field_access_summary(expr.clone()),
                                target.clone(),
                            )
                        }
                    }
                } else {
                    {
                        let base_str = emit_unified_typed_expr(
                            field_access_base(expr.clone()),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        );
                        emit_field_access_unified(
                            base_str.clone(),
                            field_access_field_at(expr.clone(), fa_si.clone()),
                            expr_field_access_summary(expr.clone()),
                            target.clone(),
                        )
                    }
                }
            },
            |expr| {
                emit_typed_call_unified(
                    expr_call_func_at(expr.clone(), si.clone()),
                    expr.children.clone(),
                    target.clone(),
                    registry.clone(),
                    scope.clone(),
                    |n| {
                        emit_unified_typed_expr(
                            n.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                )
            },
            |expr| {
                emit_typed_method_call_unified(
                    method_receiver(expr.clone()),
                    expr_method_name_at(expr.clone(), si.clone()),
                    method_arg_nodes(expr.clone()),
                    expr_method_call_semantics(expr.clone()),
                    target.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    |n| {
                        emit_unified_typed_expr(
                            n.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                )
            },
            |expr| {
                let scrut_str = emit_unified_typed_expr(
                    match_scrutinee(expr.clone()),
                    target.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    1024,
                    render_pattern.clone(),
                );
                emit_typed_match_unified(
                    scrut_str.clone(),
                    match_arm_nodes(expr.clone()),
                    target.clone(),
                    depth.clone(),
                    |node, d| {
                        emit_unified_typed_expr(
                            node.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            d.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                    render_pattern.clone(),
                    si.clone(),
                )
            },
            |expr| {
                let cond_str = emit_unified_typed_expr(
                    if_condition(expr.clone()),
                    target.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    1024,
                    render_pattern.clone(),
                );
                let if_result_type = match spec.expression_semantics.clone().if_value_form.clone() {
                    IfValueForm::IfStatement => Some(resolved_type(expr.clone())),
                    _ => None,
                };
                emit_typed_if_shared(
                    cond_str.clone(),
                    if_then_branch(expr.clone()),
                    if_else_branch(expr.clone()),
                    if_result_type.clone(),
                    depth.clone(),
                    target.clone(),
                    si.clone(),
                    |node, d| {
                        emit_unified_typed_expr(
                            node.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            d.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                )
            },
            |expr| {
                let val_str = emit_unified_typed_expr(
                    let_value(expr.clone()),
                    target.clone(),
                    registry.clone(),
                    scope.clone(),
                    depth.clone(),
                    1024,
                    render_pattern.clone(),
                );
                emit_typed_let_shared(
                    let_binding_name_at(expr.clone(), si.clone()),
                    val_str.clone(),
                    let_body(expr.clone()),
                    target.clone(),
                    |bd, sc| {
                        emit_unified_typed_expr(
                            bd.clone(),
                            target.clone(),
                            registry.clone(),
                            sc.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                    scope.clone(),
                    let_value(expr.clone()),
                )
            },
            |expr| {
                emit_typed_record_lit_unified(
                    record_lit_type_name_at(expr.clone(), si.clone()),
                    expr.children.clone(),
                    target.clone(),
                    si.clone(),
                    |n| {
                        emit_unified_typed_expr(
                            n.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                )
            },
            |expr| {
                emit_typed_string_interp_unified(
                    extract_string_interp_parts(expr.clone()),
                    target.clone(),
                    |e| {
                        emit_unified_typed_expr(
                            e.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                )
            },
            |expr| {
                emit_typed_block_join(
                    expr.children.clone(),
                    scope.clone(),
                    depth.clone(),
                    |remaining, sc, d| {
                        let prepend = if spec.block_syntax.clone().significant_whitespace.clone() {
                            false
                        } else {
                            true
                        };
                        emit_block_stmts_shared(
                            remaining.clone(),
                            Rc::new(vec![]),
                            sc.clone(),
                            d.clone(),
                            prepend.clone(),
                            |stmt, s, dd| {
                                emit_unified_typed_expr(
                                    stmt.clone(),
                                    target.clone(),
                                    registry.clone(),
                                    s.clone(),
                                    dd.clone(),
                                    1024,
                                    render_pattern.clone(),
                                )
                            },
                        )
                    },
                )
            },
            |expr| {
                emit_typed_cast_shared(
                    cast_expr(expr.clone()),
                    cast_target(expr.clone()),
                    target.clone(),
                    |child| {
                        emit_unified_typed_expr(
                            child.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                    si.clone(),
                )
            },
            |expr| {
                emit_typed_for_each_shared(
                    foreach_variable_at(expr.clone(), si.clone()),
                    foreach_collection(expr.clone()),
                    foreach_body(expr.clone()),
                    target.clone(),
                    depth.clone(),
                    si.clone(),
                    |child, s, d| {
                        emit_unified_typed_expr(
                            child.clone(),
                            target.clone(),
                            registry.clone(),
                            s.clone(),
                            d.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                    scope.clone(),
                )
            },
            |expr| {
                emit_typed_index_shared(
                    index_base(expr.clone()),
                    index_expr(expr.clone()),
                    target.clone(),
                    |child| {
                        emit_unified_typed_expr(
                            child.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                    si.clone(),
                )
            },
            |expr| {
                emit_typed_slice_shared(
                    slice_base(expr.clone()),
                    slice_start(expr.clone()),
                    slice_end(expr.clone()),
                    target.clone(),
                    |child| {
                        emit_unified_typed_expr(
                            child.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            1024,
                            render_pattern.clone(),
                        )
                    },
                    si.clone(),
                )
            },
            |expr| {
                emit_default_bin_op(
                    expr.clone(),
                    target.clone(),
                    si.clone(),
                    |child| {
                        emit_unified_typed_expr(
                            child.clone(),
                            target.clone(),
                            registry.clone(),
                            scope.clone(),
                            depth.clone(),
                            (fuel.clone() - 1),
                            render_pattern.clone(),
                        )
                    },
                    |result| result.clone(),
                )
            },
        )
    })
}

pub fn is_tco_identity_passthrough(
    arg_val: Rc<Node>,
    param_name: String,
    si: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> bool {
    match (*arg_val.expr_data.clone()).clone() {
        ExprData::ExprVar {
            binding_kind: _, ..
        } => (expr_var_name_at(arg_val.clone(), si.clone()) == param_name.clone()),
        _ => false,
    }
}

pub fn emit_typed_tco_reassign_shared(
    args: Rc<Vec<Rc<Node>>>,
    params: Rc<Vec<Rc<Node>>>,
    target: RenderTarget,
    recurse: impl Fn(Rc<Node>) -> String + Clone,
    source_indices: Rc<HashMap<String, Rc<NewlineIndex>>>,
) -> String {
    {
        let arg_values = Rc::new({
            let mut __result = Vec::new();
            for a in args.clone().iter().cloned() {
                __result.push(arg_value(a.clone()));
            }
            __result
        });
        let pairs = Rc::new({
            let mut __result = Vec::new();
            for pair in Rc::new(
                params
                    .clone()
                    .iter()
                    .cloned()
                    .enumerate()
                    .map(|(i, v)| (i as i64, v))
                    .collect::<Vec<_>>(),
            )
            .iter()
            .cloned()
            {
                if {
                    let pname = param_node_name_at(pair.1.clone(), source_indices.clone());
                    let av = match arg_values.clone().get(pair.0.clone() as usize).cloned() {
                        Some(v) => v.clone(),
                        None => pair.1.clone(),
                    };
                    !is_tco_identity_passthrough(av.clone(), pname.clone(), source_indices.clone())
                } {
                    __result.push(pair);
                }
            }
            __result
        });
        let filtered_arg_values = Rc::new({
            let mut __result = Vec::new();
            for pair in pairs.clone().iter().cloned() {
                __result.push(
                    match arg_values.clone().get(pair.0.clone() as usize).cloned() {
                        Some(v) => v.clone(),
                        None => pair.1.clone(),
                    },
                );
            }
            __result
        });
        let ordered_args = Rc::new({
            let mut __result = Vec::new();
            for av in filtered_arg_values.clone().iter().cloned() {
                __result.push(recurse(av.clone()));
            }
            __result
        });
        let param_names = Rc::new({
            let mut __result = Vec::new();
            for pair in pairs.clone().iter().cloned() {
                __result.push(emit_ident(
                    param_node_name_at(pair.1.clone(), source_indices.clone()),
                    target.clone(),
                ));
            }
            __result
        });
        shared_tco_reassign(
            ordered_args.clone(),
            param_names.clone(),
            language_spec(target.clone()),
        )
    }
}

pub fn seed_bindings(key: String, value: String) -> Rc<HashMap<String, String>> {
    v1_rt::rc_map_insert(
        v1_rt::rc_empty_map::<String, String>(),
        key.clone(),
        value.clone(),
    )
}

